from pybricks.parameters import Color, Stop
from pybricks.tools import multitask, run_task, wait

from MyBlocks import WallStart
from robot_config import DRIVE_BASE, HUB, LEFT_ATTACHMENT, RIGHT_ATTACHMENT, watch

async def Task02_Temp():
    await wait(0)
    await Preload()
    await Main_Code()
    await Closeout_Task()

async def subtask():
    # Set the left attachment to the strating position
    await LEFT_ATTACHMENT.run_target(500, 0)

async def subtask2():
    # Set the right attachment to the strating position
    await RIGHT_ATTACHMENT.run_target(500, 0)

async def Preload():
    await wait(0)
    # Print the Task Start Time
    print('M02 Task Start', watch.time() / 1000, 's', sep=", ")
    # Change the light to Red to indicate that the mission is running
    HUB.light.on(Color.RED)
    # WallStart to back into the wall slightly to take out the backlash in the
    # motor
    await WallStart()
    await multitask(
        subtask(),
        subtask2(),
    )
    # Reset the positions before your code
    DRIVE_BASE.reset(0, 0)
    LEFT_ATTACHMENT.reset_angle(0)
    RIGHT_ATTACHMENT.reset_angle(0)
    DRIVE_BASE.use_gyro(True)
    # Set the initial motor parameters
    DRIVE_BASE.settings(straight_speed=950)
    DRIVE_BASE.settings(straight_acceleration=1300)
    DRIVE_BASE.settings(turn_rate=200)
    DRIVE_BASE.settings(turn_acceleration=400)
    # Set the initial left attachment motor parameters
    LEFT_ATTACHMENT.control.limits(speed=1000)
    LEFT_ATTACHMENT.control.limits(acceleration=2000)
    LEFT_ATTACHMENT.control.limits(torque=200)
    LEFT_ATTACHMENT.settings(max_voltage=9000)
    LEFT_ATTACHMENT.control.target_tolerances(50, 3)
    # Set the initial right attachment motor parameters
    RIGHT_ATTACHMENT.control.limits(speed=1000)
    RIGHT_ATTACHMENT.control.limits(acceleration=2000)
    RIGHT_ATTACHMENT.control.limits(torque=200)
    RIGHT_ATTACHMENT.settings(max_voltage=9000)
    RIGHT_ATTACHMENT.control.target_tolerances(50, 11)

async def Main_Code():
    await wait(0)
    # YOUR CODE GOES HERE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!



    # Example of moving each motor:
    await DRIVE_BASE.straight(200)
    await LEFT_ATTACHMENT.run_angle(500, 180)
    await RIGHT_ATTACHMENT.run_angle(500, 90)
    # Example of moving all of the motors at the same time:
    await multitask(
        DRIVE_BASE.straight(-200),
        LEFT_ATTACHMENT.run_target(500, 0),
        RIGHT_ATTACHMENT.run_angle(500, 90),
    )

async def Closeout_Task():
    await wait(0)
    # Closeout the task so it is ready for the next one to start
    await LEFT_ATTACHMENT.run_target(500, 0)
    await RIGHT_ATTACHMENT.run_target(500, 0)
    print('Drive Pos.', DRIVE_BASE.distance())
    print('Left Pos.', LEFT_ATTACHMENT.angle())
    print('Right Pos.', RIGHT_ATTACHMENT.angle())
    print('M01 Task01 Finish', watch.time() / 1000, 's', sep=", ")

async def main():
    # Blank,  done to make code multitask
    # Needed due to how the blocks work
    # Anything in this multitask will be
    # executed at download
    await multitask(
        wait(0),
    )


run_task(main())